"""Payroll summary from multi-site clock exports. Usage: payroll.py INPUT_DIR OUTPUT_FILE"""
import csv
import gzip
import json
import os
import sys
from datetime import datetime, timedelta, timezone, date, time as dtime
from decimal import Decimal
from fractions import Fraction
from zoneinfo import ZoneInfo

UTC = timezone.utc
EPOCH = datetime(1970, 1, 1, tzinfo=UTC)


# ---------------------------------------------------------------- helpers
def read_text(path):
    with open(path, "rb") as f:
        raw = f.read()
    if raw[:2] == b"\x1f\x8b":
        raw = gzip.decompress(raw)
    text = raw.decode("utf-8")
    if text.startswith("\ufeff"):
        text = text[1:]
    return text


def lines_of(text):
    out = []
    for ln in text.split("\n"):
        ln = ln.rstrip("\r")
        if ln.strip() == "":
            continue
        out.append(ln)
    return out


def list_files(d):
    res = []
    if not os.path.isdir(d):
        return res
    for root, dirs, files in os.walk(d):
        dirs.sort()
        for fn in sorted(files):
            res.append(os.path.join(root, fn))
    return res


def to_epoch(dt):
    """aware datetime -> integer seconds since epoch (fractions dropped)."""
    delta = dt - EPOCH
    return delta.days * 86400 + delta.seconds


def parse_iso(s):
    s = s.strip()
    if s.endswith(("Z", "z")):
        s = s[:-1] + "+00:00"
    dt = datetime.fromisoformat(s)
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=UTC)
    return dt


def local_to_epoch(naive, tz, dst_flag=None):
    """Local wall-clock -> epoch seconds. dst_flag: True/False picks the occurrence of a
    repeated time; None picks the first occurrence."""
    cands = []
    for fold in (0, 1):
        d = naive.replace(tzinfo=tz, fold=fold)
        off = d.utcoffset()
        utc = naive - off
        back = utc.replace(tzinfo=UTC).astimezone(tz).replace(tzinfo=None)
        if back == naive:
            cands.append((utc.replace(tzinfo=UTC), bool(d.dst()), off))
    if not cands:  # nonexistent local time: use fold=0 interpretation
        d = naive.replace(tzinfo=tz, fold=0)
        return to_epoch((naive - d.utcoffset()).replace(tzinfo=UTC))
    if len(cands) == 1 or dst_flag is None:
        return to_epoch(cands[0][0])
    for utc, is_dst, _ in cands:
        if is_dst == dst_flag:
            return to_epoch(utc)
    return to_epoch(cands[0][0])


def header_rows(rows, key_cols):
    """Yield (header_map, row) for csv rows, tracking repeated header rows."""
    header = None
    for row in rows:
        cells = [c.strip() for c in row]
        if all(k in cells for k in key_cols):
            header = {name: i for i, name in enumerate(cells)}
            continue
        if header is None:
            continue
        yield header, row


def get(header, row, name):
    i = header.get(name)
    if i is None or i >= len(row):
        return ""
    return row[i].strip()


# ---------------------------------------------------------------- formats
# each parser yields (punch_id, employee, direction 'IN'/'OUT', epoch_seconds)
def parse_abbr_csv(text, tz, std_unused):
    for h, row in header_rows(csv.reader(lines_of(text)), ("Badge", "Punch")):
        badge = get(h, row, "Badge")
        pid = get(h, row, "Record")
        d = get(h, row, "Punch").upper()
        ds = get(h, row, "Date")
        ts = get(h, row, "Time")
        zone = get(h, row, "Zone").upper()
        mo, da, yr = [int(x) for x in ds.split("/")]
        parts = ts.split()
        ampm = None
        if len(parts) == 2:
            ampm = parts[1].upper()
        elif ts.upper().endswith(("AM", "PM")):
            ampm = ts[-2:].upper()
            parts = [ts[:-2].strip()]
        hh, mm, ss = (int(x) for x in (parts[0].split(":") + ["0"])[:3])
        if ampm:
            hh = hh % 12
            if ampm == "PM":
                hh += 12
        naive = datetime(yr, mo, da, hh, mm, ss)
        flag = None
        if zone.endswith("DT"):
            flag = True
        elif zone.endswith("ST"):
            flag = False
        yield pid, badge, d, local_to_epoch(naive, tz, flag)


def parse_epoch_jsonl(text, tz, std_unused):
    schema = 1
    for ln in lines_of(text):
        try:
            o = json.loads(ln)
        except ValueError:
            continue
        if not isinstance(o, dict):
            continue
        if "schema" in o and "punch_id" not in o and "id" not in o:
            try:
                schema = int(o["schema"])
            except (TypeError, ValueError):
                pass
            continue
        if o.get("heartbeat"):
            continue
        if schema == 2:
            pid, emp, d, ms = o.get("punch_id"), o.get("employee"), o.get("direction"), o.get("epoch_ms")
            if pid is None or ms is None:
                continue
            sec = int(ms) // 1000
        else:
            pid, emp, d = o.get("id"), o.get("emp"), o.get("dir")
            if pid is None or d is None:
                continue
            if o.get("ts") is not None:
                sec = int(o["ts"]) if not isinstance(o["ts"], float) else int(o["ts"] // 1)
            elif o.get("ts_ms") is not None:
                sec = int(o["ts_ms"]) // 1000
            else:
                continue
        yield str(pid), str(emp).strip(), str(d).upper(), sec


def parse_offset_csv(text, tz, std_unused):
    rows = csv.reader(lines_of(text), delimiter=";", quotechar='"')
    for h, row in header_rows(rows, ("punch_id", "employee", "event", "timestamp")):
        ev = get(h, row, "event").lower()
        d = "IN" if ev.endswith("in") else "OUT"
        yield (get(h, row, "punch_id"), get(h, row, "employee"), d,
               to_epoch(parse_iso(get(h, row, "timestamp"))))


def parse_legacy(text, tz, site_std):
    offset = None  # seconds; None -> site standard
    for ln in lines_of(text):
        t = ln[0]
        if t == "H":
            off = ln[13:18].strip()
            if off and off[0] in "+-" and len(off) >= 5:
                sec = int(off[1:3]) * 3600 + int(off[3:5]) * 60
                offset = -sec if off[0] == "-" else sec
            else:
                offset = None
        elif t == "D":
            pid = ln[1:9]
            badge = ln[9:15].strip()
            d = "IN" if ln[15] == "I" else "OUT"
            dt = ln[16:30]
            naive = datetime(int(dt[0:4]), int(dt[4:6]), int(dt[6:8]), int(dt[8:10]), int(dt[10:12]),
                             int(dt[12:14]))
            as_utc = to_epoch(naive.replace(tzinfo=UTC))
            off = offset if offset is not None else site_std(naive)
            emp = badge if badge.startswith("E") else "E" + badge
            yield pid, emp, d, as_utc - off


def parse_de_tsv(text, tz, std_unused):
    rows = csv.reader(lines_of(text), delimiter="\t", quoting=csv.QUOTE_NONE)
    for h, row in header_rows(rows, ("Ausweis", "Buchung")):
        d = "IN" if get(h, row, "Buchung").upper() == "K" else "OUT"
        dd, mo, yr = [int(x) for x in get(h, row, "Datum").split(".")]
        tp = (get(h, row, "Uhrzeit").split(":") + ["0"])[:3]
        naive = datetime(yr, mo, dd, int(tp[0]), int(tp[1]), int(tp[2]))
        z = get(h, row, "Zeitzone").upper()
        flag = True if z == "MESZ" else (False if z == "MEZ" else None)
        yield get(h, row, "Nr"), get(h, row, "Ausweis"), d, local_to_epoch(naive, tz, flag)


def parse_local_csv(text, tz, std_unused):
    for h, row in header_rows(csv.reader(lines_of(text)), ("employee_id", "direction", "local_time")):
        d = get(h, row, "direction").upper()
        naive = datetime.strptime(get(h, row, "local_time"), "%Y-%m-%d %H:%M:%S")
        yield get(h, row, "punch_ref"), get(h, row, "employee_id"), d, local_to_epoch(naive, tz, None)


def parse_local_jsonl(text, tz, std_unused):
    for ln in lines_of(text):
        try:
            o = json.loads(ln)
        except ValueError:
            continue
        if not isinstance(o, dict) or not isinstance(o.get("punch"), dict):
            continue
        p = o["punch"]
        if p.get("id") is None or p.get("at") is None:
            continue
        pid = p["id"]
        pid = str(int(pid)) if isinstance(pid, (int, float)) else str(pid).strip()
        naive = datetime.strptime(str(p["at"]).strip(), "%Y-%m-%d %H:%M:%S")
        yield pid, str(p.get("badge")).strip(), str(p.get("type")).upper(), local_to_epoch(naive, tz, None)


PARSERS = {
    "abbr-csv": parse_abbr_csv,
    "epoch-jsonl": parse_epoch_jsonl,
    "offset-csv": parse_offset_csv,
    "legacy-fixed": parse_legacy,
    "de-tsv": parse_de_tsv,
    "local-csv": parse_local_csv,
    "local-jsonl": parse_local_jsonl,
}


# ---------------------------------------------------------------- main logic
def read_csv_file(path):
    return list(csv.DictReader(lines_of(read_text(path))))


def main(indir, outfile):
    with open(os.path.join(indir, "period.json")) as f:
        period = json.load(f)
    pstart = date.fromisoformat(period["start"])
    pend = date.fromisoformat(period["end"])
    cutoff = parse_iso(period["corrections_cutoff"])

    sites = {}
    for r in read_csv_file(os.path.join(indir, "sites.csv")):
        sites[r["site"].strip()] = (ZoneInfo(r["timezone"].strip()), r["format"].strip())

    employees = []
    emp_home = {}
    for r in read_csv_file(os.path.join(indir, "employees.csv")):
        eid = r["employee_id"].strip()
        if eid not in emp_home:
            employees.append(eid)
        emp_home[eid] = r["home_site"].strip()

    rates = {}
    for r in read_csv_file(os.path.join(indir, "rates.csv")):
        rates.setdefault(r["employee_id"].strip(), []).append(
            (date.fromisoformat(r["effective_from"].strip()), Decimal(r["hourly_rate"].strip())))
    for v in rates.values():
        v.sort(key=lambda x: x[0])

    # 1. collect punches: key (site, id) -> dict
    punches = {}
    ever = set()
    for site, (tz, fmt) in sorted(sites.items()):
        parser = PARSERS[fmt]

        def site_std(naive, tz=tz):
            guess = naive.replace(tzinfo=UTC).astimezone(tz)
            return int((guess.utcoffset() - (guess.dst() or timedelta(0))).total_seconds())

        for path in list_files(os.path.join(indir, "exports", site)):
            for pid, emp, d, sec in parser(read_text(path), tz, site_std):
                key = (site, pid)
                ever.add(key)
                if key not in punches:
                    punches[key] = {"site": site, "id": pid, "emp": emp, "dir": d, "t": sec}

    # 2. corrections
    corrs = []
    for path in list_files(os.path.join(indir, "corrections")):
        try:
            text = read_text(path)
        except (UnicodeDecodeError, OSError):
            continue
        for r in csv.DictReader(lines_of(text)):
            r = {(k or "").strip(): (v or "").strip() for k, v in r.items()}
            if not r.get("correction_id"):
                continue
            corrs.append(r)
    sel = []
    for r in corrs:
        try:
            issued = parse_iso(r["issued_at"])
        except ValueError:
            continue
        if issued > cutoff:
            continue
        sel.append((issued, r["correction_id"], r))
    sel.sort(key=lambda x: (x[0], x[1]))
    applied = 0
    for _, _, r in sel:
        key = (r.get("site", ""), r.get("punch_id", ""))
        act = r.get("action", "").lower()
        if act == "void":
            if key in punches:
                del punches[key]
                applied += 1
        elif act == "set":
            if key in punches and r.get("time"):
                punches[key]["t"] = to_epoch(parse_iso(r["time"]))
                applied += 1
        elif act == "add":
            if key not in ever and key[0] in sites and r.get("time"):
                d = r.get("type", "").upper()
                punches[key] = {"site": key[0], "id": key[1], "emp": r.get("employee", ""),
                                "dir": "IN" if d == "IN" else "OUT",
                                "t": to_epoch(parse_iso(r["time"]))}
                ever.add(key)
                applied += 1

    emp_set = set(employees)
    byemp = {}
    for p in punches.values():
        if p["emp"] in emp_set:
            byemp.setdefault(p["emp"], []).append(p)

    # 4 helper: rounding
    def rounded(p):
        tz = sites[p["site"]][0]
        t = p["t"]
        off = int(datetime.fromtimestamp(t, UTC).astimezone(tz).utcoffset().total_seconds())
        loc = t + off
        loc = (loc + 180) // 360 * 360
        return loc - off

    home_tz = {e: sites[emp_home[e]][0] for e in employees if emp_home[e] in sites}

    def workday(e, t):
        return datetime.fromtimestamp(t, UTC).astimezone(home_tz[e]).date()

    def in_period(d):
        return pstart <= d <= pend

    res = {e: {"shifts": 0, "paid_minutes": 0, "overtime_minutes": 0, "night_minutes": 0,
               "gross": Fraction(0)} for e in employees}
    exc = {"open_shifts": 0, "orphan_outs": 0, "duplicates_dropped": 0, "corrections_applied": applied}

    for e in employees:
        plist = byemp.get(e, [])
        if not plist or e not in home_tz:
            continue
        plist.sort(key=lambda p: (p["t"], 0 if p["dir"] == "OUT" else 1, p["site"], p["id"]))
        kept = []
        last = None
        for p in plist:
            p["r"] = rounded(p)
            if last is not None and last["dir"] == p["dir"] and p["t"] - last["t"] <= 300:
                if in_period(workday(e, p["r"])):
                    exc["duplicates_dropped"] += 1
                continue
            kept.append(p)
            last = p
        shifts = []
        cur = None
        for p in kept:
            if p["dir"] == "IN":
                if cur is not None and in_period(workday(e, cur["r"])):
                    exc["open_shifts"] += 1
                cur = p
            else:
                if cur is not None and p["r"] - cur["r"] <= 16 * 3600:
                    shifts.append((cur, p))
                    cur = None
                else:
                    if cur is not None:
                        if in_period(workday(e, cur["r"])):
                            exc["open_shifts"] += 1
                        cur = None
                    if in_period(workday(e, p["r"])):
                        exc["orphan_outs"] += 1
        if cur is not None and in_period(workday(e, cur["r"])):
            exc["open_shifts"] += 1

        rows = []
        for i, o in shifts:
            wd = workday(e, i["r"])
            if not in_period(wd):
                continue
            worked = max(0, (o["r"] - i["r"]) // 60)
            paid = worked - 30 if worked > 360 else worked
            night = min(night_minutes(i["r"], o["r"], sites[i["site"]][0]), paid)
            rows.append({"in": i["r"], "wd": wd, "paid": paid, "night": night})
        rows.sort(key=lambda r: r["in"])
        daycum = {}
        weekcum = {}
        for r in rows:
            c = daycum.get(r["wd"], 0)
            daily_ot = max(0, c + r["paid"] - max(c, 480))
            daycum[r["wd"]] = c + r["paid"]
            monday = r["wd"] - timedelta(days=r["wd"].weekday())
            w = weekcum.get(monday, 0)
            nonot = r["paid"] - daily_ot
            weekly_ot = max(0, w + nonot - max(w, 2400))
            weekcum[monday] = w + nonot
            ot = daily_ot + weekly_ot
            reg = r["paid"] - ot
            rate = None
            for eff, rt in rates.get(e, []):
                if eff <= r["wd"]:
                    rate = rt
            rate = Fraction(rate) if rate is not None else Fraction(0)
            pay = rate * (reg + Fraction(3, 2) * ot) / 60 + rate * Fraction(15, 100) * r["night"] / 60
            s = res[e]
            s["shifts"] += 1
            s["paid_minutes"] += r["paid"]
            s["overtime_minutes"] += ot
            s["night_minutes"] += r["night"]
            s["gross"] += pay

    out_emps = {}
    tot = {"shifts": 0, "paid_minutes": 0, "overtime_minutes": 0, "night_minutes": 0}
    tot_cents = 0
    for e in employees:
        s = res[e]
        cents = int((s["gross"] * 100 + Fraction(1, 2)) // 1)
        out_emps[e] = {"shifts": s["shifts"], "paid_minutes": s["paid_minutes"],
                       "overtime_minutes": s["overtime_minutes"], "night_minutes": s["night_minutes"],
                       "gross": "%d.%02d" % divmod(cents, 100)}
        for k in tot:
            tot[k] += s[k]
        tot_cents += cents
    tot["gross"] = "%d.%02d" % divmod(tot_cents, 100)
    result = {"period": {"start": period["start"], "end": period["end"]},
              "employees": out_emps, "exceptions": exc, "totals": tot}
    d = os.path.dirname(os.path.abspath(outfile))
    os.makedirs(d, exist_ok=True)
    with open(outfile, "w") as f:
        json.dump(result, f, indent=1)


def night_minutes(t_in, t_out, tz):
    """Elapsed minutes in [t_in, t_out) within 22:00-06:00 local time of tz."""
    if t_out <= t_in:
        return 0
    d0 = datetime.fromtimestamp(t_in, UTC).astimezone(tz).date() - timedelta(days=1)
    d1 = datetime.fromtimestamp(t_out, UTC).astimezone(tz).date() + timedelta(days=1)
    total = 0
    d = d0
    while d <= d1:
        a = local_to_epoch(datetime.combine(d, dtime(22, 0)), tz)
        b = local_to_epoch(datetime.combine(d + timedelta(days=1), dtime(6, 0)), tz)
        lo, hi = max(a, t_in), min(b, t_out)
        if hi > lo:
            total += hi - lo
        d += timedelta(days=1)
    return total // 60


if __name__ == "__main__":
    if len(sys.argv) != 3:
        sys.exit("usage: payroll.py INPUT_DIR OUTPUT_FILE")
    main(sys.argv[1], sys.argv[2])
